namespace LSE.AutoCADElectrical.ProjectEnvironment;
public static class DiagnosticsService {
 public static string BuildReport(){var x=new List<string>{"LSE_Env diagnostics  "+DateTime.Now.ToString("s"),"Build: "+BuildInfo.Release,"Assembly: "+typeof(DiagnosticsService).Assembly.Location,"Version: "+(typeof(DiagnosticsService).Assembly.GetName().Version?.ToString()??"?")+"  runtime "+Environment.Version+"  user "+Environment.UserName,""};
  AppSettings s;try{s=SettingsService.Load();x.Add("Settings: "+SettingsService.SettingsPath+(File.Exists(SettingsService.SettingsPath)?"":"  (not written yet; defaults in use)"));}catch(Exception ex){x.Add("Settings: FAIL "+ex.Message);return string.Join(Environment.NewLine,x);}
  x.Add("  Rules JSON: "+s.RulesConfigPath+(File.Exists(s.RulesConfigPath)?"":"  MISSING (built-in defaults in use)"));x.Add("  Profiles folder: "+s.ProfilesFolder+(Directory.Exists(s.ProfilesFolder)?"":"  (not created yet"+(VaultProbe.InVaultWorkingFolder(s.ProfilesFolder)?" - not downloaded yet? In Vault Explorer select the folder and Get Latest Version":"")+")"));x.Add("  Template project: "+s.TemplateProjectPath+(File.Exists(s.TemplateProjectPath)?"":"  MISSING (template-based wire schemes unavailable)"+(VaultProbe.InVaultWorkingFolder(s.TemplateProjectPath)?" - not downloaded yet? In Vault Explorer select the folder and Get Latest Version":"")));
  x.Add("  Backups: "+s.BackupFolderName+" keep "+s.BackupsToKeep+"  |  apply to drawings "+s.ApplyToDrawings+"  |  From/To "+s.ComputeFromTo+"  |  retag after apply "+s.RetagAfterApply+"  |  reactivate "+s.ReactivateAfterApply);x.Add(VaultProbe.Report(""));x.Add("  Logs: "+SettingsService.LogFolder);x.Add("  Snapshots: "+SettingsService.SnapshotFolder);x.Add("");
  EnvRules r;try{r=RulesService.Load(s.RulesConfigPath);x.Add("Rules: "+r.Source);}catch(Exception ex){x.Add("Rules: FAIL "+ex.Message);return string.Join(Environment.NewLine,x);}
  x.Add($"  Setting map: {r.Settings.Count} rows, {r.Settings.Count(m=>m.Mapped)} mapped, {r.Settings.Count(m=>!m.Mapped)} not mapped, {r.Settings.Count(m=>m.Confidence.Equals("verified",StringComparison.OrdinalIgnoreCase))} verified on a workstation");
  foreach(var g in r.Settings.GroupBy(m=>m.Group)){x.Add("  "+g.Key);foreach(var m in g)x.Add($"    {m.Key,-18} {m.Where,-28} {m.Confidence}{(m.Protected?"  protected":"")}{(m.Note.Length>0?"  | "+m.Note:"")}");}
  x.Add("  Wire schemes: "+string.Join("; ",r.WireSchemes.Select(w=>w.Name+(w.IsFromTo?" [From/To]":w.FromTemplate?" [template]":""))));x.Add("  From/To: blocks "+string.Join(",",r.FromTo.WireNumberBlocks)+" attr "+r.FromTo.WireNumberAttribute+" insert "+r.FromTo.InsertBlockName+(r.FromTo.InsertMissing?"":" (off)")+" connections "+r.FromTo.ConnectionAttributePattern+" tags "+string.Join(",",r.FromTo.TagAttributes)+" tolerances join "+r.FromTo.JoinTolerance+" connect "+r.FromTo.ConnectTolerance+" gap "+r.FromTo.GapTolerance+" mark "+r.FromTo.MarkTolerance);x.Add("");
  try{var profiles=ProfileService.Load(s);x.Add($"Profiles: {profiles.Count} in {s.ProfilesFolder}"+(Directory.Exists(SettingsService.BundledProfilesFolder)?"  (bundled samples in "+SettingsService.BundledProfilesFolder+")":"  (no bundled samples folder next to the DLL)"));foreach(var p in profiles)x.Add($"  {p.Display}: scheme {(p.Scheme.Length>0?p.Scheme:"(none)")}{(r.Scheme(p.Scheme) is null&&p.Scheme.Length>0?" MISSING from the rules":"")}, {p.Values.Count} value(s), {p.Properties.Count+p.Options.Count+p.Drawing.Count} raw override(s){(p.FromTo is not null?", own From/To settings":"")}  [{p.FilePath}]");}catch(Exception ex){x.Add("Profiles: FAIL "+ex.Message);}
  x.Add("");x.Add("Unverified on a workstation: the ?[n] indexes and WD_M attribute names in the setting map (use LSEENVSNAPSHOT), the wire-number block name and attribute, the symbol connection attributes, and every AutoCAD write. See README.");
  return string.Join(Environment.NewLine,x);}
}
